  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/proc/cygdrive/c/Users/eliza/Documents/GitHub/neurorythmes/node_modules/.pnpm/@11ty+eleventy-dev-server@2.0.8/node_modules/@11ty/eleventy-dev-server/node_modules:/proc/cygdrive/c/Users/eliza/Documents/GitHub/neurorythmes/node_modules/.pnpm/@11ty+eleventy-dev-server@2.0.8/node_modules/@11ty/node_modules:/proc/cygdrive/c/Users/eliza/Documents/GitHub/neurorythmes/node_modules/.pnpm/@11ty+eleventy-dev-server@2.0.8/node_modules:/proc/cygdrive/c/Users/eliza/Documents/GitHub/neurorythmes/node_modules/.pnpm/node_modules"
