  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../../../../../../@11ty+eleventy-dev-server@2.0.8/node_modules/@11ty/eleventy-dev-server/cmd.js" $args
